  set loopConfiguration(loop) {
    if (!this.isVod || (this.ads && Env.isIos[0])) {
      Logger.print('api', 'cannot set loop for live or DVR streams or player loaded with ads on iOS');
      this.loop = false;
      return;
    }
    if (typeof loop === 'boolean' && this.dom.video) {
      this.dom.video.loop = this.loop = loop;
    }
  }

