  /** 
   * @typedef {object} PlayerSize
   * @property {number} [width]
   * @property {number} [height]
   * @return {PlayerSize}
   */
  getPlayerSize() {
    return {
      width: FW.getPrecisionWidthWithPaddingAndBorder(this.dom.container),
      height: FW.getPrecisionHeightWithPaddingAndBorder(this.dom.container)
    };
  }

  /**
   * @type {(x:string, y:string, fullscreenFullWindowMode:boolean) => void}
   */
  setPlayerSize(inputPlayerSize) {
    if (typeof inputPlayerSize.width !== 'number' || inputPlayerSize.width <= 0 ||
      typeof inputPlayerSize.height !== 'number' || inputPlayerSize.height <= 0) {
      this.rmpUtils.warning(1003);
      return;
    }
    if (!this.playerReady) {
      this.rmpUtils.warning(1004);
      return;
    }
    let validatedFullscreenFullWindowMode = false;
    if (typeof inputPlayerSize.fullscreenFullWindowMode === 'boolean') {
      validatedFullscreenFullWindowMode = inputPlayerSize.fullscreenFullWindowMode;
    }
    if (this.isInFullscreen && !this.fullscreenFullWindowMode) {
      this.rmpUtils.warning(1026);
      return;
    }
    if (this.iframeMode || (this.autoHeightMode && !this.fullscreenFullWindowMode)) {
      this.rmpUtils.warning(1027);
      return;
    }
    const width = inputPlayerSize.width;
    const height = inputPlayerSize.height;
    Logger.print('api', 'playerSize called with width: ' + width + ' and height: ' + height);
    if (validatedFullscreenFullWindowMode) {
      this.width = width;
      this.height = height;
    } else {
      this.rmpSizeManagement.initialWidth = width;
      this.width = width;
      this.rmpSizeManagement.initialHeight = height;
      this.height = height;
    }
    if (this.audioOnly) {
      this.height = 48;
    }
    this.resize();
  }

  /** 
   * @typedef {object} Ratio
   * @property {number} player
   * @property {number} media
   * @return {Ratio}
   */
  get ratio() {
    const currentRatio = {
      player: -1,
      media: -1
    };
    const playerSize = this.getPlayerSize();
    if (playerSize.width > 0 && playerSize.height > 0) {
      currentRatio.player = playerSize.width / playerSize.height;
    }
    if (this.dom.video) {
      const videoWidth = this.dom.video.videoWidth;
      const videoHeight = this.dom.video.videoHeight;
      if (videoWidth > 0 && videoHeight > 0) {
        currentRatio.media = videoWidth / videoHeight;
      }
    }
    return currentRatio;
  }

