  /** 
   * seek to chapter based on input. Returns Promise that resolves if seekToChapter successful (rejects otherwise)
   * @param {number} chapterIndex - the new chapter to seek to
   * @return {Promise<>}
   */
  seekToChapter(chapterIndex) {
    return new Promise((resolve, reject) => {
      if (!this.playerReady) {
        this.rmpUtils.warning(1004);
        reject(this.warningData);
        return;
      }
      const rmpChapters = this.rmpChapters;
      if (rmpChapters && rmpChapters.array.length > 0 && typeof chapterIndex === 'number' &&
        chapterIndex > -1 && typeof rmpChapters.array[chapterIndex] !== 'undefined') {
        this.seekTo(rmpChapters.array[chapterIndex].start).then(() => {
          resolve();
        }).catch(warning => {
          this.rmpUtils.warning(1016, warning);
          reject(this.warningData);
        });
      } else {
        this.rmpUtils.warning(1003);
        reject(this.warningData);
      }
    });
  }

