  /**
   * @private
   */
  #onAutoplayResultKnown(resolve) {
    this.off('autoplayfailure', this.onAutoplayResultKnownFn);
    this.off('autoplaysuccess', this.onAutoplayResultKnownFn);
    if (!this.autoplay) {
      resolve('no-autoplay');
    } else {
      if (this.autoplayMode === 'autoplay-with-sound') {
        resolve('autoplay-with-sound');
      } else {
        resolve('muted-autoplay');
      }
    }
  }

  /** 
   * Returns Promise that resolves to autoplay result at the moment player is trying to play content for first time. no-autoplay means autoplay attempt was a failure. Note that this method never rejects. 
   * autoplay-with-sound | muted-autoplay | no-autoplay
   * @type {() => string} 
   */
  getAutoplayResult() {
    return new Promise(resolve => {
      if (this.autoplayResultKnown || this.requestAutoplayCapabilitiesData) {
        resolve(this.autoplayMode);
      } else {
        this.onAutoplayResultKnownFn = this.#onAutoplayResultKnown.bind(this, resolve);
        this.one('autoplayfailure', this.onAutoplayResultKnownFn);
        this.one('autoplaysuccess', this.onAutoplayResultKnownFn);
      }
    });
  }

