  /**
   * @private
   */
  #setSharingUrl(url) {
    if (typeof url === 'string' && url && this.rmpSharing) {
      const filteredSharingNetworks = this.rmpSharing.filteredSharingNetworks;
      this.sharingUrl = url;
      const container = this.dom.container;
      if (filteredSharingNetworks.indexOf('facebook') > -1) {
        const facebookIcon = container.querySelector('.rmp-i-facebook');
        if (facebookIcon) {
          facebookIcon.setAttribute('href', 'https://www.facebook.com/sharer/sharer.php?u=' +
            encodeURIComponent(url));
        }
      }
      if (filteredSharingNetworks.indexOf('x') > -1 || filteredSharingNetworks.indexOf('twitter') > -1) {
        const twitterIcon = container.querySelector('.rmp-i-x');
        if (twitterIcon) {
          twitterIcon.setAttribute('href', 'https://x.com/share?url=' +
            encodeURIComponent(url));
        }
      }
      if (filteredSharingNetworks.indexOf('linkedin') > -1) {
        const linkedinIcon = container.querySelector('.rmp-i-linkedin');
        if (linkedinIcon) {
          linkedinIcon.setAttribute('href', 'https://www.linkedin.com/shareArticle?mini=true&url=' +
            encodeURIComponent(url));
        }
      }
      if (filteredSharingNetworks.indexOf('reddit') > -1) {
        const redditIcon = container.querySelector('.rmp-i-reddit');
        if (redditIcon) {
          redditIcon.setAttribute('href', 'https://www.reddit.com/submit?url=' +
            encodeURIComponent(url));
        }
      }
      if (filteredSharingNetworks.indexOf('whatsapp') > -1) {
        const whatsappIcon = container.querySelector('.rmp-i-whatsapp');
        if (whatsappIcon) {
          whatsappIcon.setAttribute('href', 'whatsapp://send?text=' +
            encodeURIComponent(url));
        }
      }
      const sharingLinkInput = container.querySelector('#rmp-sharing-link-' + this.id);
      if (sharingLinkInput) {
        sharingLinkInput.value = url;
      }
    }
  }

  /**
   * @private
   */
  #setSharingCode(sharingCode) {
    const sharingCodeInput = this.dom.container.querySelector('#rmp-sharing-code-' + this.id);
    if (typeof sharingCode === 'string' && sharingCode && sharingCodeInput) {
      this.sharingCode = sharingCode;
      sharingCodeInput.value = this.sharingCode;
    }
  }


  /** 
   * @type {(data: SharingData) => void} 
   */
  set sharingData(data) {
    if (data && typeof data === 'object' && (data.url || data.code)) {
      if (data.url) {
        this.#setSharingUrl(data.url);
      }
      if (data.code) {
        this.#setSharingCode(data.code);
      }
    }
  }

