  /** 
   * @private
   */
  #onAdDestroyLoadAds() {
    if (this.rmpAdsIma) {
      this.off('adcontentresumerequested', this.onAdDestroyLoadAdsFn);
      this.rmpAdsIma.resetAdsForNewRequest();
      this.rmpAdsIma.requestImaAds(this.adTagUrl);
    } else if (this.rmpAdsRmpVast) {
      this.off('addestroyed', this.onAdDestroyLoadAdsFn);
      this.rmpAdsRmpVast.restoreContentUI();
      this.rmpAdsRmpVast.requestRmpVastAds(this.adTagUrl);
    }
    if (this.adOutStream) {
      this.#resetOutstreamAdUI();
    }
  }

  /** 
   * load a VAST tag at input parameter adTag - pass optional adTagWaterfall parameter for client-side waterfalling. Returns Promise that resolves if loadAds successful (rejects otherwise)
   * @param {string} adTag - URI to VAST tag
   * @param {string[]} [adTagWaterfall] - optional Array of VAST tag URI to be used for client-side waterfalling
   * @param {boolean} [firstPlayAdRequest]
   * @return {Promise<>}
   */
  loadAds(adTag, adTagWaterfall, firstPlayAdRequest) {
    return new Promise((resolve, reject) => {
      if (typeof adTag !== 'string' || adTag === '') {
        this.rmpUtils.warning(1003);
        reject(this.warningData);
        return;
      }
      if (!this.playerReady) {
        this.rmpUtils.warning(1004);
        reject(this.warningData);
        return;
      }
      if (!this.ads) {
        this.rmpUtils.warning(10005);
        reject(this.warningData);
        return;
      }
      if (this.adImaDai) {
        this.rmpUtils.warning(10012);
        reject(this.warningData);
        return;
      }
      if (this.googleCastConnected) {
        this.rmpUtils.warning(10013);
        reject(this.warningData);
        return;
      }
      this.adTagUrl = this.rmpAdsHelpers.replaceAdTagVar(adTag);
      this.rmpInitManagement.originalAdTagUrl = this.adTagUrl;
      let isInternalLoadAdsRequest = false;
      let hasAdTagWaterfall = false;
      if (Array.isArray(adTagWaterfall) && adTagWaterfall[0]) {
        if (adTagWaterfall[0] === 'internal') {
          isInternalLoadAdsRequest = true;
        } else {
          this.adTagWaterfall = adTagWaterfall;
          this.rmpInitManagement.originalAdTagWaterfall = this.adTagWaterfall;
          hasAdTagWaterfall = true;
        }
      }
      if (firstPlayAdRequest) {
        if (this.rmpAdsIma) {
          this.rmpAdsIma.requestImaAds(this.adTagUrl);
        } else if (this.rmpAdsRmpVast) {
          this.rmpAdsRmpVast.requestRmpVastAds(this.adTagUrl);
        }
        resolve();
        return;
      }
      Logger.print('api', 'loadAds API called with URI: ' + this.adTagUrl);
      this.onAdDestroyLoadAdsFn = this.#onAdDestroyLoadAds.bind(this);
      let _onAdLoaded, _onAdError;
      _onAdLoaded = () => {
        this.off('aderror', _onAdError);
        resolve();
      };
      _onAdError = () => {
        this.off('adloaded', _onAdLoaded);
        if (hasAdTagWaterfall || isInternalLoadAdsRequest) {
          resolve();
        } else {
          this.rmpUtils.warning(10016);
          reject(this.warningData);
        }
      };
      if (this.rmpAdsIma) {
        if (!this.rmpPlaybackManagement.adImaDisplayContainerInitialized) {
          this.rmpUtils.warning(10014);
          reject(this.warningData);
          return;
        }
        this.one('adloaded', _onAdLoaded);
        this.one('aderror', _onAdError);
        if (this.linearAdOnStage) {
          this.on('adcontentresumerequested', this.onAdDestroyLoadAdsFn);
          this.stopAds().catch(warning => {
            this.rmpUtils.warning(1021, warning);
            reject(this.warningData);
          });
        } else {
          this.onAdDestroyLoadAdsFn();
        }
      } else if (this.rmpAdsRmpVast) {
        if (!this.rmpVast.initialized) {
          this.rmpUtils.warning(10015);
          reject(this.warningData);
          return;
        }
        this.one('adloaded', _onAdLoaded);
        this.one('aderror', _onAdError);
        if (this.linearAdOnStage) {
          this.on('addestroyed', this.onAdDestroyLoadAdsFn);
          this.stopAds().catch(error => {
            this.rmpUtils.warning(1021, error);
            reject(this.warningData);
          });
        } else {
          this.onAdDestroyLoadAdsFn();
        }
      }

    });
  }

  /** 
   * stop playing current advertisement and free up player resources. Returns Promise that resolves if stopAds successful (rejects otherwise - will also reject if no ad on stage)
   * @return {Promise<>}
   */
  stopAds() {
    Logger.print('api', 'stopAds requested');
    return new Promise((resolve, reject) => {
      if (!this.playerReady) {
        this.rmpUtils.warning(1004);
        reject(this.warningData);
        return;
      }
      if (!this.adOnStage) {
        this.rmpUtils.warning(10017);
        reject(this.warningData);
        return;
      }
      if (this.imaAdsManager) {
        if (!this.adLinear) {
          this.imaAdOnStage = false;
          this.imaAdsManager.stop();
          resolve();
        } else {
          this.one('adcontentresumerequested', () => {
            resolve();
          });
          this.imaAdsManager.stop();
        }
      } else if (this.rmpVast) {
        this.one('addestroyed', () => {
          resolve();
        });
        this.rmpVast.stopAds();
      }
    });
  }

  /** 
   * skip current advertisement and free up player resources - if the advertisement can be skipped. Returns Promise that resolves if skipAd successful (rejects otherwise - will also reject if ad is not skippable)
   * @return {Promise<>}
   */
  skipAd() {
    return new Promise((resolve, reject) => {
      if (!this.playerReady) {
        this.rmpUtils.warning(1004);
        reject(this.warningData);
        return;
      }
      if (!this.adOnStage) {
        this.rmpUtils.warning(10018);
        reject(this.warningData);
        return;
      }
      if (this.adSkippableState) {
        if (this.imaAdsManager) {
          this.one('adcontentresumerequested', () => {
            resolve();
          });
          this.imaAdsManager.skip();
        } else if (this.rmpVast) {
          if (this.rmpVast.isSkippableAd || this.vpaidCreative) {
            this.one('addestroyed', () => {
              resolve();
            });
            this.rmpVast.skipAd();
          }
        }
      } else {
        this.rmpUtils.warning(10019);
        reject(this.warningData);
      }
    });
  }

