  /** 
   * @param {number} adSlotWidth
   * @param {number} adSlotHeight
   * @param {object} [opt_settings]
   * @return {object[]}
   */
  getCompanionAds(adSlotWidth, adSlotHeight, opt_settings) {
    if (!this.ads) {
      this.rmpUtils.warning(10005);
      return [{}];
    }
    if (!this.playerReady) {
      this.rmpUtils.warning(1004);
      return [{}];
    }
    let companionWidth = 300;
    if (typeof adSlotWidth === 'number' && adSlotWidth > 0) {
      companionWidth = adSlotWidth;
    }
    let companionHeight = 250;
    if (typeof adSlotHeight === 'number' && adSlotHeight > 0) {
      companionHeight = adSlotHeight;
    }
    if (this.adParser === 'ima') {
      if (this.adImaDai) {
        if (typeof this.currentAdForCompanion.getCompanionAds === 'function') {
          return this.currentAdForCompanion.getCompanionAds();
        }
      } else if (this.imaAdsManager) {
        const companionAds = this.currentAdForCompanion.getCompanionAds(companionWidth, companionHeight, opt_settings);
        if (Array.isArray(companionAds) && companionAds.length > 0) {
          return companionAds;
        }
      }
    } else if (this.rmpVast) {
      const companionAds = this.rmpVast.getCompanionAdsList(companionWidth, companionHeight);
      if (Array.isArray(companionAds) && companionAds.length > 0) {
        return companionAds;
      }
    }
    return [{}];
  }

  /** 
   * Detect ad-blocker. Returns a Promise that resolves to a Boolean indicating if an ad blocker has been detected on page (true === adblocker detected) or rejects if ads setting is false and this is not a AWS Media Tailor stream
   * @return {Promise<boolean>}
   */
  getAdBlock() {
    return new Promise((resolve, reject) => {
      if (this.adParserLoadError) {
        resolve(true);
      } else if (this.rmpAdsHelpers) {
        AdBlocker.hasAdblock().then(adBlockerDetected => {
          if (adBlockerDetected) {
            resolve(true);
          } else {
            resolve(false);
          }
        });
      } else {
        this.rmpUtils.warning(10003);
        reject(this.warningData);
      }
    });
  }

