  /** 
   * Load a new playlist item into the player. Returns Promise that resolves if setPlaylistItem is successful or rejects if an error occurs while trying to load new playlist item
   * @param {number} index - the new playlist item to load
   * @return {Promise<>} 
   */
  setPlaylistItem(index) {
    return new Promise((resolve, reject) => {

      if (typeof index !== 'number' || index < 0) {
        this.rmpUtils.warning(1003);
        reject(this.warningData);
        return;
      }
      if (!this.rmpPlaylist) {
        this.rmpUtils.warning(7001);
        reject(this.warningData);
        return;
      }

      let _onSrcChanged, _onError;
      _onSrcChanged = () => {
        this.off('error', _onError);
        resolve();
      };
      _onError = () => {
        this.off('srcchanged', _onSrcChanged);
        this.rmpUtils.error(709);
        reject(this.warningData);
      };
      this.one('srcchanged', _onSrcChanged);
      this.one('error', _onError);

      this.rmpPlaylist.loadPlaylistItem(index);

    });
  }

