  /******************************************* SRC API *******************************************/
  #resumeSetSrc(src, pdIndex) {
    // src changing
    this.changingSrc = true;
    this.rmpApiSrc = new ApiSrc(this);
    this.rmpApiSrc.init(src, pdIndex);
  }

  /** 
   * change player content source based on input
   * return Promise that resolves if successful (rejects otherwise)
   * @param {Src} src
   * @param {number} [pdIndex]
   * @return {Promise<>}
   */
  setSrc(src, pdIndex) {
    return new Promise((resolve, reject) => {

      this.setSrcResolve = resolve;
      this.setSrcReject = reject;

      if (typeof src !== 'object') {
        this.rmpUtils.warning(1003);
        this.rejectPromise('setSrc', this.warningData);
        return;
      }
      if (!this.playerReady) {
        this.rmpUtils.warning(1004);
        this.rejectPromise('setSrc', this.warningData);
        return;
      }
      if (this.readingFps || this.readingOutstream) {
        this.rmpUtils.warning(12006);
        this.rejectPromise('setSrc', this.warningData);
        return;
      }
      if (this.changingSrc) {
        this.rmpUtils.warning(12000);
        this.rejectPromise('setSrc', this.warningData);
        return;
      }

      const validSrcType = ['hls', 'dash', 'mp4', 'webm', 'm4a', 'mp3', 'ogg', 'fps'];
      const foundSrc = validSrcType.find(srcType => {
        return typeof src[srcType] !== 'undefined';
      });
      if (typeof foundSrc === 'undefined') {
        this.rmpUtils.warning(1003);
        this.rejectPromise('setSrc', this.warningData);
        return;
      }

      if (this.streamType === 'nosupport') {
        this.rmpUtils.warning(12001);
        this.rejectPromise('setSrc', this.warningData);
        return;
      }

      // setSrc after ready but before hlsjsinstancecreated or shakainstancecreated
      if (this.readingMse && this.msePreloadRequested && !this.hlsjsInstanceCreated && !this.shakaInstanceCreated) {
        Logger.print('api', 'hls.js or Shaka player instance is still being created - wait for creation before setSrc');
        if (this.readingHlsJS) {
          this.one('hlsjsinstancecreated', () => {
            Logger.print('api', 'hls.js created - continue setSrc');
            this.#resumeSetSrc(src, pdIndex);
          });
        } else {
          this.one('shakainstancecreated', () => {
            Logger.print('api', 'Shaka player created - continue setSrc');
            this.#resumeSetSrc(src, pdIndex);
          });
        }
      } else {
        this.#resumeSetSrc(src, pdIndex);
      }
    });
  }

